CREATE TABLE IF NOT EXISTS user_2fa (user_id BIGINT UNSIGNED PRIMARY KEY, secret VARCHAR(64) NOT NULL, enabled TINYINT(1) DEFAULT 0, recovery_codes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS oauth_clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id VARCHAR(100) UNIQUE NOT NULL, client_secret_hash CHAR(64) NOT NULL, name VARCHAR(150) NOT NULL, redirect_uris TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS oauth_authorization_codes (code_hash CHAR(64) PRIMARY KEY, client_id VARCHAR(100) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, redirect_uri TEXT NOT NULL, scope TEXT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS oauth_access_tokens (token_hash CHAR(64) PRIMARY KEY, client_id VARCHAR(100) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, scope TEXT NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_keys (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,name VARCHAR(150) NOT NULL,key_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NULL,revoked_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,invoice_no VARCHAR(100) UNIQUE NOT NULL,subtotal DECIMAL(14,2) DEFAULT 0,tax DECIMAL(14,2) DEFAULT 0,discount DECIMAL(14,2) DEFAULT 0,total DECIMAL(14,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'issued',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tax_rates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,rate DECIMAL(8,4) NOT NULL,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) UNIQUE NOT NULL,type VARCHAR(20) DEFAULT 'percent',value DECIMAL(14,2) NOT NULL,active TINYINT(1) DEFAULT 1,starts_at DATETIME NULL,ends_at DATETIME NULL,usage_limit INT NULL,used_count INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,tenant_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(120) NULL,entity_id VARCHAR(120) NULL,ip VARCHAR(64) NULL,user_agent VARCHAR(500) NULL,meta JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(tenant_id),INDEX(action));
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(190) PRIMARY KEY,setting_value LONGTEXT NULL,encrypted TINYINT(1) DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webauthn_credentials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,credential_id VARBINARY(1024) NOT NULL,public_key TEXT NOT NULL,sign_count BIGINT UNSIGNED DEFAULT 0,transports VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(user_id,credential_id(255)));
